// ---------------------------------------------------------------------------
// Cierre determinista post-calculate_estimate.
// Convierte la respuesta del backend en el texto que ve el cliente.
// NINGÚN LLM toca este texto ni la cifra (Adenda 1.1a).
// 21/10 (D39.5): en el caso 4, si el presupuesto es NUEVO (creado === true),
// el texto avisa del email; es justo cuando el flujo lanza WF7 (G2).
// ---------------------------------------------------------------------------

// 1) Extraer la respuesta de calculate_estimate del envoltorio del MCP Client.
//    Forma real verificada: $json.content[0].text. En esta ejecución llegó
//    como OBJETO; en D17.1 (observation) otro dato llegó como STRING JSON.
//    Aceptamos las dos para no depender de cómo lo entregue n8n.
let datos = null;
let incidencia = null;

const bruto = $json.content?.[0]?.text;   // ?. = si algo es undefined, devuelve
                                          // undefined en vez de romper
if (typeof bruto === 'string') {
  try {
    datos = JSON.parse(bruto);            // string JSON -> objeto
  } catch (e) {
    incidencia = 'texto_no_es_json';      // llegó texto, pero no es JSON
  }
} else if (bruto && typeof bruto === 'object') {
  datos = bruto;                          // ya viene como objeto
} else {
  incidencia = 'respuesta_mcp_sin_contenido';
}

// 2) Formato de moneda español. Intl.NumberFormat viene de serie en Node.js.
//    Nota: en es-ES, las cifras de 4 dígitos NO llevan punto de millar
//    ("4840,00 €") porque así lo fija la norma (CLDR/RAE); de 5 en adelante
//    sí ("13.915,00 €"). Es intencionado, no un error.
const eur = new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR' });

// El backend manda los importes como string decimal ("4840.00") para no
// perder precisión. Aquí solo se muestran, no se calcula nada con ellos,
// así que convertir a Number para formatear es seguro.
function importeValido(valor) {
  const n = Number(valor);
  return (valor !== null && valor !== undefined && valor !== '' && Number.isFinite(n)) ? n : null;
}

// 3) Clasificación. Cada caso exige TODAS sus condiciones; lo que no encaje
//    exactamente cae en el caso 5. Nunca se muestra una cifra "por si acaso".
let caso = 5;
let texto;

if (datos && incidencia === null) {
  const gate   = datos.requiere_aprobacion;
  const motivo = datos.motivo_gate;
  const min    = importeValido(datos.importe_min_con_iva);
  const max    = importeValido(datos.importe_max_con_iva);

  if (datos.status === 'requiere_revision') {
    caso = 1;
  } else if (gate === true && (motivo === 'cambios_estructurales' || motivo === 'ambos')) {
    caso = 2;
  } else if (gate === true && motivo === 'importe_superior_umbral') {
    caso = 3;
  } else if (gate === false && motivo === null && datos.status === 'presupuesto_enviado'
             && min !== null && max !== null && min <= max) {
    caso = 4;
    // D39.5: la frase del email SOLO si este presupuesto se ha creado en esta
    // llamada (creado === true). Es la misma condición con la que el nodo
    // email_presupuesto lanza WF7: en un reintento (creado = false) no sale
    // email, así que tampoco se promete.
    const avisoEmail = datos.creado === true
      ? 'En unos minutos recibirás este resumen en tu email. '   // con espacio final
      : '';                                                       // sin email, sin frase
    texto =
      `Según los datos que nos has facilitado, la estimación orientativa para tu reforma ` +
      `es de entre ${eur.format(min)} y ${eur.format(max)} (IVA incluido).\n\n` +
      `Es una pre-estimación: el presupuesto definitivo se confirma tras una visita ` +
      `técnica, que es gratuita. ` + avisoEmail +                 // la frase va aquí, si toca
      `Si tienes alguna duda o quieres solicitar la visita, dímelo.`;
  } else {
    incidencia = 'combinacion_no_prevista';   // p. ej. un status nuevo del backend
  }
}

// 4) Textos de los casos sin cifra (D18.5: en Gate NUNCA se muestra importe).
//    Casos 2 y 3 (Gate), revisados el 2026-10-04 por D19.3: un cliente con
//    Gate NO pide la visita desde el chat (POST /visits responde 409); es
//    administración quien le llama, avisada al momento por WF2 (email +
//    Telegram). Solo se promete lo que se puede cumplir: "en horario laboral".
if (caso === 1) {
  texto =
    'No hemos podido calcular automáticamente una estimación para tu proyecto. ' +
    'Un técnico lo revisará y se pondrá en contacto contigo.';
} else if (caso === 2) {
  // 27/11 (retirada del asesor del Gate): el texto explica POR QUÉ la visita
  // no se reserva en el chat (obra de mayor envergadura, técnico especializado,
  // la coordina administración). Sigue sin prometer nada que no se cumpla.
  texto =
    'Como tu proyecto incluye o puede incluir cambios estructurales (muros, tabiques o estructura), ' +
    'es una obra de mayor envergadura: antes de darte una cifra, un técnico especializado tiene que verlo en persona. ' +
    'Por eso esta visita no se reserva desde el chat: la coordina nuestro equipo de administración con la agenda del técnico. ' +
    'Te llamarán lo antes posible, en horario laboral, para acordarla. La visita es gratuita.';
} else if (caso === 3) {
  texto =
    'Por el alcance de tu proyecto, un técnico especializado tiene que revisarlo personalmente antes de darte una cifra. ' +
    'Esta revisión no se reserva desde el chat: la coordina nuestro equipo de administración. ' +
    'Te llamarán lo antes posible, en horario laboral, para darte una información más precisa.';
} else if (caso === 5) {
  texto =
    'Hemos recibido tus datos correctamente. Un técnico revisará tu solicitud ' +
    'y se pondrá en contacto contigo.';
}

// 4b) 27/11: «qué suele incluir» en los casos 2 y 3 (Gate), sin LLM.
//     DEUDA DECLARADA: COPIA LITERAL de incluye_tipico de get_business_rules
//     (Supabase), tomada el 27/11/2026. Si cambia en la base de datos, hay
//     que actualizarla AQUÍ. En N1, el backend la devolverá con el presupuesto.
//     Si no hay texto para la combinación o falla la lectura, el mensaje sale
//     sin este párrafo (nunca se rompe el turno).
const INCLUYE_TIPICO = {
  "bano|alto": "Retirada del baño actual y desescombro. Renovación de la fontanería y la electricidad del baño. Revestimientos de paredes y suelo nuevos de gama alta. Se cambia todo: plato de ducha o bañera, inodoro, lavabo con mueble de baño y grifería, de gama alta. Permite redistribuir los elementos dentro del baño, sin tirar ni mover tabiques.",
  "bano|basico": "Retirada del baño actual y desescombro. Renovación de la fontanería y la electricidad del baño. Alicatado de paredes y suelo nuevos de gama básica. Se cambia todo: plato de ducha o bañera, inodoro, lavabo con mueble de baño y grifería, de gama básica. Permite redistribuir los elementos dentro del baño, sin tirar ni mover tabiques.",
  "bano|medio": "Retirada del baño actual y desescombro. Renovación de la fontanería y la electricidad del baño. Alicatado de paredes y suelo nuevos de calidad media. Se cambia todo: plato de ducha o bañera, inodoro, lavabo con mueble de baño y grifería, de calidad media. Permite redistribuir los elementos dentro del baño, sin tirar ni mover tabiques.",
  "cocina|alto": "Retirada de la cocina actual y desescombro. Renovación de la fontanería y la electricidad de la cocina. Revestimientos de paredes y suelo nuevos de gama alta. Se cambia todo: muebles altos y bajos, encimera, fregadero y grifería, de gama alta. Incluye electrodomésticos de gama alta, integrados en el mobiliario. Permite redistribuir los elementos dentro de la cocina, sin tirar ni mover tabiques.",
  "cocina|basico": "Retirada de la cocina actual y desescombro. Renovación de la fontanería y la electricidad de la cocina. Alicatado de paredes y suelo nuevos de gama básica. Se cambia todo: muebles altos y bajos, encimera, fregadero y grifería, de gama básica. Montaje y conexión de tus electrodomésticos; los aparatos no están incluidos. Permite redistribuir los elementos dentro de la cocina, sin tirar ni mover tabiques.",
  "cocina|medio": "Retirada de la cocina actual y desescombro. Renovación de la fontanería y la electricidad de la cocina. Alicatado de paredes y suelo nuevos de calidad media. Se cambia todo: muebles altos y bajos, encimera, fregadero y grifería, de calidad media. Montaje y conexión de tus electrodomésticos; los aparatos no están incluidos. Permite redistribuir los elementos dentro de la cocina, sin tirar ni mover tabiques.",
  "integral_vivienda|alto": "Retirada y desescombro de lo que se renueva. Renovación de la electricidad y la fontanería de la vivienda. Suelos de gama alta y pintura de paredes y techos. Cocina y baño completos de gama alta, con electrodomésticos de gama alta incluidos. Carpintería interior a medida y diseño personalizado de los espacios.",
  "integral_vivienda|basico": "Retirada y desescombro de lo que se renueva. Renovación de la electricidad y la fontanería de la vivienda. Suelos nuevos y pintura de paredes y techos. Cocina y baño completos de gama básica. Se mantienen las puertas y la carpintería interior existentes. Los electrodomésticos no están incluidos.",
  "integral_vivienda|medio": "Retirada y desescombro de lo que se renueva. Renovación de la electricidad y la fontanería de la vivienda. Suelos nuevos y pintura de paredes y techos. Cocina y baño completos de calidad media. Puertas interiores nuevas de calidad media. Los electrodomésticos no están incluidos.",
  "parcial_acabados|alto": "Pintura de paredes y techos. Suelo nuevo de gama alta, por ejemplo madera natural o porcelánico de gran formato. Puertas interiores y frentes de armario de gama alta. No incluye instalaciones: si necesitas renovar la electricidad o la fontanería, el técnico lo valora aparte en la visita.",
  "parcial_acabados|basico": "Pintura de paredes y techos. Suelo nuevo de gama básica. Se mantienen las puertas existentes. No incluye instalaciones: si necesitas renovar la electricidad o la fontanería, el técnico lo valora aparte en la visita.",
  "parcial_acabados|medio": "Pintura de paredes y techos. Suelo nuevo de calidad media, por ejemplo laminado de alta resistencia o gres. Puertas interiores nuevas de calidad media. No incluye instalaciones: si necesitas renovar la electricidad o la fontanería, el técnico lo valora aparte en la visita.",
  "pintura|alto": "Protección de suelos y muebles y limpieza al terminar. Quitar el gotelé y alisar las paredes, con reparación de grietas y desconchones. Pintura plástica en paredes y techos, con los colores que elijas. No incluye pintar puertas, ventanas o radiadores.",
  "pintura|basico": "Protección de suelos y muebles y limpieza al terminar. Pintura plástica blanca en paredes y techos de las estancias indicadas. No incluye reparar grietas, quitar gotelé ni alisar paredes, ni pintar puertas, ventanas o radiadores.",
  "pintura|medio": "Protección de suelos y muebles y limpieza al terminar. Reparación de pequeñas grietas, agujeros y desconchones. Pintura plástica en paredes y techos, con los colores que elijas. No incluye quitar gotelé ni alisar paredes, ni pintar puertas, ventanas o radiadores."
};
const NOMBRE_TIPO = { bano: 'una reforma de baño', cocina: 'una reforma de cocina',
  integral_vivienda: 'una reforma integral de vivienda', parcial_acabados: 'una reforma parcial de acabados',
  pintura: 'un trabajo de pintura' };
const NOMBRE_NIVEL = { basico: 'básicos', medio: 'medios', alto: 'altos' };
if (caso === 2 || caso === 3) {
  try {
    const p = $('leer_pendiente').first().json;          // fila del cliente (tipo y nivel)
    const txt = INCLUYE_TIPICO[p.tipo_reforma + '|' + p.nivel_acabados];
    const tipo = NOMBRE_TIPO[p.tipo_reforma], nivel = NOMBRE_NIVEL[p.nivel_acabados];
    if (txt && tipo && nivel) {
      const cierre = caso === 2
        ? ' Los cambios estructurales que nos has indicado los valorará el técnico en la visita, y después te dará el precio y el plazo.'
        : ' El precio y el plazo te los dará el técnico tras revisarlo.';
      texto += '\n\nComo orientación, ' + tipo + ' con acabados ' + nivel + ' suele incluir: ' +
        txt.charAt(0).toLowerCase() + txt.slice(1) + cierre;
    }
  } catch (e) { /* sin párrafo de orientación */ }
}

// 5) Salida. "output" es el campo que lee el Chat Trigger (VERIFICADO en
//    ejecución real, 2026-09-24). Se devuelven los IDs y el caso para el
//    router, para WF2 y para WF7, pero NUNCA los importes: WF2 y WF7 los leen
//    del backend (aviso del Gate y ficha), con su propia llave.
return {
  json: {
    output: texto,
    caso,                                         // email_presupuesto exige caso 4
    incidencia,                                   // null si todo fue normal
    oportunidad_id: datos?.oportunidad_id ?? null,
    presupuesto_id: datos?.presupuesto_id ?? null,
    requiere_aprobacion: datos?.requiere_aprobacion ?? null,
    motivo_gate: datos?.motivo_gate ?? null,
    // true solo si el presupuesto se creó en ESTA llamada. gate_HITL (WF2) y
    // email_presupuesto (WF7) lo exigen: si n8n reintenta o el cálculo se
    // repite, el backend contesta creado=false y no sale un segundo aviso ni
    // un segundo email (decisión P2 de calculate-estimate; G2 de D39).
    // ?? null: si no se pudo leer la respuesta, "no sabemos" (null) no es lo
    // mismo que "no" (false).
    creado: datos?.creado ?? null,
  },
};

// ---------------------------------------------------------------------------
// chat_tipo_reforma · Aviso técnico cuando falla un paso (WF4). 2026-10-15.
// ROB-02/ROB-04 (24/11) + H-186-1: sirve para tres salidas de ERROR y para el caso 5 de pintar_estimacion: Agente2_asesor,
// MCP Client (el cálculo tras el «sí») y AI Agent (Agente 1: OpenAI caído o clave
// inválida). $prevNode.name dice cuál falló.
// H-186-4 (25/11): también avisa cuando falla la consulta del estado de la sesión (backend caído) o cuando
// el estado no tiene ruta (router_estado_sesion). Esos fallos se repiten en TODOS los turnos de todos los
// clientes: se avisa una sola vez cada 15 minutos por tipo de fallo (memoria estática del flujo publicado).
// Sin datos del cliente: solo el id de la oportunidad. Mode: Run Once for All Items.
// ---------------------------------------------------------------------------
const j = $input.first().json;                                     // { error: ... }
// H-186-1 (24/11): también llega desde pintar_estimacion. Solo avisa si el cálculo
// no dio una respuesta válida (caso 5: el MCP contestó sin error pero sin datos).
// 27/11 (revisión externa H2): también el caso 1 (requiere_revision: faltan reglas). Al cliente se le promete una llamada.
if ($prevNode.name === 'pintar_estimacion' && j.caso !== 5 && j.caso !== 1) return [];   // cifra o Gate normales: sin aviso
const e = j.error ?? (j.incidencia ? `incidencia: ${j.incidencia}`
  : (j.caso === 1 ? 'status requiere_revision: falta la tarifa, el umbral o el IVA en reglas_negocio' : null));  // error del nodo, o incidencia del cálculo
const texto = !e ? 'sin detalle' : (typeof e === 'string' ? e
  : [e.code, e.message, e.description].filter((x) => typeof x === 'string' && x.trim() !== '').join(' · ') || 'error sin texto');
const nodo = $prevNode.name;                                       // 'Agente2_asesor', 'MCP Client' o 'AI Agent'
let oportunidad_id = null;                                         // id de la oportunidad, si se sabe
try { oportunidad_id = $('crear_lead_confirmado').first(0).json.oportunidad_id ?? null; } catch (err) { oportunidad_id = null; }  // ROB-02: lead recién creado
if (oportunidad_id === null) {                                     // Agente 2: el lead ya existía
  try { oportunidad_id = $('Consultar_estado_sesion').first(0).json.oportunidad_id ?? null; } catch (err) { oportunidad_id = null; }
}
// H-186-4: fallos de la consulta de estado. Un aviso por tipo de fallo cada 15 min (sin datos del cliente).
let detalle = texto;
if (nodo === 'router_estado_sesion') detalle = `estado_oportunidad: ${j.estado_oportunidad ?? 'sin dato'}`;
// 26/11 (tarde): un fallo del modelo (clave, parámetros, OpenAI caído) se repite en TODOS los turnos: 71 avisos en 11 min
// en la prueba con razonamiento. Los agentes usan el mismo control: un aviso por paso y error cada 15 min.
const AGENTES = ['Agente2_asesor', 'Agente2_gate', 'AI Agent']; // pasos con modelo de lenguaje
if (nodo === 'Consultar_estado_sesion' || nodo === 'router_estado_sesion' || AGENTES.includes(nodo)) {
  const memoria = $getWorkflowStaticData('global');
  const avisos = memoria.ultimosAvisos ?? {};
  const clave = AGENTES.includes(nodo) ? `${nodo}|${texto.slice(0, 120)}` : `${nodo}|${j.estado_oportunidad ?? ''}`; // agentes: por texto del error
  const ahora = Date.now();
  if (avisos[clave] && ahora - avisos[clave] < 15 * 60 * 1000) return [];   // ya avisado hace menos de 15 min
  avisos[clave] = ahora;
  memoria.ultimosAvisos = avisos;
}
const QUE = {                                                      // texto del aviso según el paso
  'MCP Client': 'El cálculo de la estimación falló después de guardar el lead (el cliente no recibió cifra). El cliente espera que le llamen y NO sale en la lista diaria',
  'pintar_estimacion': 'El cálculo no devolvió una estimación válida después de guardar el lead (el cliente no recibió cifra). El cliente espera que le llamen y NO sale en la lista diaria',
  'AI Agent': 'El Agente 1 no pudo responder (el cliente recibió el mensaje de problema técnico)',
  'Agente2_asesor': 'El Agente 2 no pudo responder',
'Agente2_gate': 'El asesor de los clientes en revisión no pudo responder',
  'Consultar_estado_sesion': 'No se pudo consultar el estado de la sesión: el backend no responde (el cliente recibió el mensaje de problema técnico)',
  'router_estado_sesion': 'La sesión no tiene ninguna ruta (el cliente recibió el mensaje de problema técnico)',
};
const que = QUE[nodo] ?? `El paso ${nodo} falló`;                // cualquier otro: genérico
return [{ json: {
  flujo: $workflow.name,                  // este flujo
  nodo,                                   // el paso que ha fallado
  mensaje_error: `${que}: ${detalle}`,
  oportunidad_id,
  ejecucion_id: String($execution.id),
} }];

// =====================================================================
// Nodo Code "leer_confirmacion" (D51). Workflow: chat_tipo_reforma.
// D57 (23/11): teléfono y nota limpiados por código (bloque D57).
// D58 (24/11): negativa a guardar los datos -> texto fijo y ruta 'negativa'.
// Va DESPUÉS de "leer_pendiente" (Data table, Get) y ANTES del Switch
// "ruta_confirmacion". Decide, SIN modelo, si el mensaje del cliente
// confirma el resumen pendiente. Modo: Run Once for All Items.
// =====================================================================

// --- 1. Datos del turno ---------------------------------------------
const chat = $('When chat message received').first().json;   // mensaje del cliente y su sesión
// 27/11 (revisión externa H7 y H11): tope de 2000 caracteres (OWASP LLM10) y el cliente no puede abrir una «nota del sistema».
const mensaje = String(chat.chatInput ?? '').slice(0, 2000)
  .replace(/^\s*\[\s*nota del sistema/i, '(texto del cliente');                 // texto tal cual (si falta, vacío)
const sessionId = chat.sessionId;                             // identifica la conversación

// --- D57 (23/11): limpieza determinista del teléfono y de la nota ---------
// MISMO BLOQUE en pintar_resumen y en leer_confirmacion: lo que ve el cliente
// en el resumen es exactamente lo que se guarda. No depende del modelo.

// Teléfono: quita espacios, puntos, guiones, paréntesis y barras; "00" -> "+".
// H-175-3: un "+" seguido de solo 9 cifras que empiezan por 6-9 es un número
// español con un "+" que el cliente no escribió: se quita. Devuelve null si
// no quedan de 9 a 15 cifras (con "+" opcional).
function limpiarTelefono(v) {
  let t = String(v ?? '').replace(/[\s.\-()\/]/g, '');        // separadores fuera
  if (/^00\d/.test(t)) t = '+' + t.slice(2);                   // 0034... -> +34...
  if (/^\+[6-9]\d{8}$/.test(t)) t = t.slice(1);                // "+" falso (H-175-3)
  return /^\+?\d{9,15}$/.test(t) ? t : null;                   // válido o null
}

// Nota (resumen_solicitud): se borra ENTERA cada frase que tenga un dato
// personal. C6 (prueba 176, A1-54): la dirección llegó al lead.
function tieneTelefono(f) {                                    // 9 o más cifras seguidas o con separadores
  return (f.match(/\+?\d[\d\s.\-()]{7,}\d/g) || [])
    .some(m => m.replace(/\D/g, '').length >= 9);
}
const DATO_PERSONAL = [
  /[^\s@]+@[^\s@]+\.[^\s@]+/,                                  // email
  /(^|[\s,(])c\/\s*\S/i,                                       // "c/ Mayor"
  /\b(calle|avenida|avda|plaza|pza|paseo|camino|carretera|ronda|traves[ií]a|urbanizaci[oó]n|portal|escalera|c[oó]digo postal)\b/i,  // dirección
  /\bn(º|°|o\.|úm\.?|úmero)\s*\d/i,                            // "nº 12", "número 12"
  /\b(salud|enferm\w*|discapacidad|silla de ruedas|movilidad|dependencia|embaraz\w*|beb[eé]s?|padre|madre|hij[oa]s?|abuel[oa]s?|marido|esposa|esposo|pareja|suegr[oa]s?|m[eé]dic[oa]s?|operaci[oó]n)\b/i,  // salud y familia
];
function limpiarNota(v) {
  const frases = String(v ?? '').replace(/\s+/g, ' ').trim()   // una sola línea
    .split(/(?<=[.!?])\s+/);                                   // frase a frase
  return frases
    .filter(f => f !== '' && !tieneTelefono(f) && !DATO_PERSONAL.some(p => p.test(f)))
    .join(' ').trim();                                         // lo que queda, o ''
}
// --- fin del bloque D57 ----------------------------------------------------

// --- D58 (24/11): negativa a que se guarden los datos (C3, A1-59) ----------
// Si el cliente dice que NO quiere que se guarden sus datos, el código responde
// con un texto fijo y borra lo pendiente; el modelo no interviene (mismo
// principio que D51 y D57). Las preguntas («¿no guardáis nada?») no cuentan.
function normalizarNeg(t) {
  return String(t ?? '').toLowerCase()                          // minúsculas
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')           // sin tildes
    .replace(/\s+/g, ' ').trim();                               // espacios simples
}
const NEGATIVA = [
  // «no quiero que guardéis nada», «no guardéis mis datos», «no registréis los datos»
  /\bno\b[^.!]{0,30}\b(guard|almacen|registr|conserv)\w*\b[^.!]{0,20}\b(nada|mis datos|los datos)\b/,
  // «no quiero dar mis datos», «no quiero daros los datos», «no deseo facilitar mis datos»
  /\bno\b[^.!]{0,20}\b(quiero|deseo)\b[^.!]{0,10}\b(dar|daros|facilitar|facilitaros|dejar|dejaros)\b[^.!]{0,10}\b(mis|los) datos\b/,
  // «borrad mis datos», «eliminad los datos», «quiero que borréis mis datos»
  /\b(borr|elimin|suprim)\w*\b[^.!]{0,15}\b(mis|los) datos\b/,
];
function esNegativa(t) {
  if (/[?¿]/.test(t)) return false;                             // una pregunta no es una negativa
  const n = normalizarNeg(t);                                   // texto comparable
  return NEGATIVA.some(p => p.test(n));                         // alguna de las tres formas
}
const TEXTO_NEGATIVA = 'De acuerdo, no guardaremos tus datos. Sin ellos no podemos preparar la estimación.';
// --- fin del bloque D58 ------------------------------------------------------

// --- 2. Fila pendiente de esta sesión ---------------------------------
// leer_pendiente devuelve una fila por item; si no hay ninguna, n8n
// entrega un item vacío ({}) porque el nodo lleva "Always Output Data".
const filas = $input.all()                                    // todos los items recibidos
  .map(i => i.json)                                           // nos quedamos con los datos
  .filter(f => f && f.session_id === sessionId);              // solo filas de ESTA sesión
// Si hubiera más de una (no debería), vale la más reciente (id mayor).
filas.sort((a, b) => Number(b.id) - Number(a.id));            // ordena de mayor a menor id
const crudo = filas[0] ?? null;                               // la última, o null si no hay
// D57: se guarda lo mismo que vio el cliente: teléfono y nota limpios.
// Si el teléfono no vale (no debería: pintar_resumen ya lo comprobó), se deja
// como está y el backend lo rechaza (rama nota_error_guardado).
const pendiente = crudo === null ? null : { ...crudo,
  telefono: limpiarTelefono(crudo.telefono) ?? crudo.telefono,
  resumen_solicitud: limpiarNota(crudo.resumen_solicitud) };

// --- 3. Lista cerrada de síes (decisión de Gabi, 13/11) ---------------
// Se comparan ya normalizados: minúsculas, sin acentos y sin signos.
const SIES = new Set([
  'si', 'correcto', 'es correcto', 'todo correcto', 'si correcto',   // "sí" y "si" quedan iguales
  'vale', 'ok', 'de acuerdo', 'confirmo', 'asi es', 'todo bien',
  'perfecto',
  'sip', 'sii', 'si si', 'claro', 'claro que si'                     // R4 (18/11): síes coloquiales
]);

// R4 (18/11, prueba 172): un sí de la lista seguido SOLO de palabras de
// cortesía también confirma ("si, todo bien, gracias"). Lista cerrada:
// cualquier otra palabra ("pero", "cambia", "no"...) deja de ser un sí.
const CORTESIA = new Set([
  'gracias', 'muchas', 'mil', 'todo', 'bien', 'perfecto', 'genial',  // palabras que no cambian nada
  'correcto', 'de', 'acuerdo', 'vale', 'ok', 'esta', 'asi', 'es'
]);

// ¿Es un sí? Exacto en la lista, o "sí de la lista" + solo cortesía.
function esSi(t) {
  if (SIES.has(t)) return true;                               // caso de siempre
  for (const s of SIES) {                                     // prueba cada sí de la lista
    if (t.startsWith(s + ' ')) {                              // empieza por ese sí y sigue algo
      const resto = t.slice(s.length + 1).split(' ');         // las palabras que siguen
      if (resto.every(p => CORTESIA.has(p))) return true;     // todas de cortesía -> sí
    }
  }
  return false;                                               // cualquier otra cosa: no es sí
}

// Normaliza: "¡Sí, correcto!" -> "si correcto".
function normalizar(t) {
  return t
    .toLowerCase()                                            // mayúsculas -> minúsculas
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')         // quita tildes (í -> i)
    .replace(/[.,;:!¡?¿…"'«»()\-]/g, ' ')                     // signos -> espacio
    .replace(/\s+/g, ' ')                                     // espacios repetidos -> uno
    .trim();                                                  // sin espacios en los extremos
}

// --- 4. Caducidad: 24 horas (decisión de Gabi, 13/11) ------------------
const CADUCIDAD_MS = 24 * 60 * 60 * 1000;                     // 24 h en milisegundos
function caducada(fila) {
  const t = Date.parse(fila.updatedAt ?? fila.createdAt);    // fecha de la última escritura
  if (!Number.isFinite(t)) return true;                       // fecha ilegible -> no fiarse
  return (Date.now() - t) > CADUCIDAD_MS;                     // más de 24 h -> caducada
}

// Lista los 8 datos pendientes, uno por línea, para el agente.
const CAMPOS = ['nombre', 'email', 'telefono', 'tipo_reforma', 'nivel_acabados',
  'm2', 'incluye_cambios_estructurales', 'resumen_solicitud'];     // columnas de la tabla
function datosPendientes(fila) {
  return CAMPOS.map(c => '- ' + c + ': ' + String(fila[c] ?? '')).join('\n'); // "- campo: valor"
}

// --- 5. Decisión ------------------------------------------------------
let ruta;                                                     // a qué rama va el turno
let textoAgente = mensaje;                                    // lo que leerá el Agente 1

let textoCliente = null;                                      // D58: solo en la ruta 'negativa'

if (esNegativa(mensaje)) {                                    // D58: va primero, haya o no pendiente
  ruta = 'negativa';                                          // no pasa por el modelo
  textoCliente = TEXTO_NEGATIVA;                              // texto fijo para el cliente
} else if (!pendiente) {
  ruta = 'sin_pendiente';                                     // nada que confirmar: como hoy
} else if (caducada(pendiente)) {
  ruta = 'caducado';                                          // se borra y se empieza de nuevo
} else if (esSi(normalizar(mensaje))) {                 // R4: sí exacto o sí + cortesía
  ruta = 'confirmado';                                        // ÚNICO camino que guarda
} else {
  ruta = 'no_confirmado';                                     // vuelve al agente con contexto
  // El agente no vio el resumen (lo pintó el código), así que se lo damos.
  textoAgente =
    '[Nota del sistema, no la escribió el cliente] El cliente vio este resumen ' +
    'y NO lo ha confirmado:\n' + datosPendientes(pendiente) +
    '\nSu respuesta: «' + mensaje + '»\n' +
    'Atiende su respuesta. Si corrige un dato, vuelve a llamar a la herramienta ' +
    'con TODOS los datos (los que no cambian, iguales).';
}

// --- 6. Salida: un solo item ------------------------------------------
// sessionId va en la salida porque la memoria del agente lo lee de aquí.
// D58: 'output' es el campo que lee el nodo existente «Responder_chat Agente1»: no hace falta un nodo nuevo.
return [{ json: { sessionId, chatInput: textoAgente, ruta, pendiente, output: textoCliente } }];

// =====================================================================
// Nodo Code "nota_error_guardado" (D51). Workflow: chat_tipo_reforma.
// Va en la salida de ERROR de "crear_lead_confirmado": el cliente dijo
// "sí", pero el backend NO guardó (dato rechazado o fallo técnico).
// Prepara el turno para el Agente 1: no se guarda nada y el agente pide
// el dato que falla. Modo: Run Once for All Items.
// =====================================================================

const chat = $('When chat message received').first().json;   // la sesión del chat
const e = $input.first().json.error;                          // el error del nodo HTTP

// Texto del error en una línea y recortado: va al agente, no al cliente.
const detalle = !e ? 'sin detalle'                            // no llegó error
  : (typeof e === 'string' ? e                                // ya es texto
    : [e.message, e.description].filter(x => typeof x === 'string' && x.trim() !== '').join(' · ') || 'sin detalle');
const corto = detalle.replace(/\s+/g, ' ').trim().slice(0, 300);   // una línea, máx. 300 caracteres

const nota =
  '[Nota del sistema, no la escribió el cliente] El cliente confirmó el resumen, ' +
  'pero el sistema NO pudo guardar los datos. Detalle técnico: ' + corto + '\n' +
  'Si el detalle señala un dato (email, teléfono, superficie...), explica en español ' +
  'sencillo cuál hay que corregir y pide solo ese dato. Si no señala ningún dato, di que ' +
  'ha habido un problema técnico y que lo intente de nuevo en unos minutos.';

// Misma forma que leer_confirmacion: el agente lee chatInput y la memoria, sessionId.
return [{ json: { sessionId: chat.sessionId, chatInput: nota, ruta: 'error_guardado' } }];

// =====================================================================
// Nodo Code "pintar_resumen" (D51). Workflow: chat_tipo_reforma.
// D57 (23/11): teléfono y nota limpiados por código (bloque D57).
// Va DESPUÉS de "leer_pendiente_tras_agente" (Data table, Get), en la
// rama en la que el Agente 1 llamó a su herramienta. Escribe el resumen
// que ve el cliente con los valores EXACTOS de la tabla. Ningún modelo
// redacta este texto. Modo: Run Once for All Items.
// =====================================================================

const sessionId = $('When chat message received').first().json.sessionId; // sesión del chat

// --- D57 (23/11): limpieza determinista del teléfono y de la nota ---------
// MISMO BLOQUE en pintar_resumen y en leer_confirmacion: lo que ve el cliente
// en el resumen es exactamente lo que se guarda. No depende del modelo.

// Teléfono: quita espacios, puntos, guiones, paréntesis y barras; "00" -> "+".
// H-175-3: un "+" seguido de solo 9 cifras que empiezan por 6-9 es un número
// español con un "+" que el cliente no escribió: se quita. Devuelve null si
// no quedan de 9 a 15 cifras (con "+" opcional).
function limpiarTelefono(v) {
  let t = String(v ?? '').replace(/[\s.\-()\/]/g, '');        // separadores fuera
  if (/^00\d/.test(t)) t = '+' + t.slice(2);                   // 0034... -> +34...
  if (/^\+[6-9]\d{8}$/.test(t)) t = t.slice(1);                // "+" falso (H-175-3)
  return /^\+?\d{9,15}$/.test(t) ? t : null;                   // válido o null
}

// Nota (resumen_solicitud): se borra ENTERA cada frase que tenga un dato
// personal. C6 (prueba 176, A1-54): la dirección llegó al lead.
function tieneTelefono(f) {                                    // 9 o más cifras seguidas o con separadores
  return (f.match(/\+?\d[\d\s.\-()]{7,}\d/g) || [])
    .some(m => m.replace(/\D/g, '').length >= 9);
}
const DATO_PERSONAL = [
  /[^\s@]+@[^\s@]+\.[^\s@]+/,                                  // email
  /(^|[\s,(])c\/\s*\S/i,                                       // "c/ Mayor"
  /\b(calle|avenida|avda|plaza|pza|paseo|camino|carretera|ronda|traves[ií]a|urbanizaci[oó]n|portal|escalera|c[oó]digo postal)\b/i,  // dirección
  /\bn(º|°|o\.|úm\.?|úmero)\s*\d/i,                            // "nº 12", "número 12"
  /\b(salud|enferm\w*|discapacidad|silla de ruedas|movilidad|dependencia|embaraz\w*|beb[eé]s?|padre|madre|hij[oa]s?|abuel[oa]s?|marido|esposa|esposo|pareja|suegr[oa]s?|m[eé]dic[oa]s?|operaci[oó]n)\b/i,  // salud y familia
];
function limpiarNota(v) {
  const frases = String(v ?? '').replace(/\s+/g, ' ').trim()   // una sola línea
    .split(/(?<=[.!?])\s+/);                                   // frase a frase
  return frases
    .filter(f => f !== '' && !tieneTelefono(f) && !DATO_PERSONAL.some(p => p.test(f)))
    .join(' ').trim();                                         // lo que queda, o ''
}
// --- fin del bloque D57 ----------------------------------------------------

// --- 1. La fila pendiente más reciente de esta sesión -----------------
const filas = $input.all()                                    // items de la tabla
  .map(i => i.json)                                           // solo los datos
  .filter(f => f && f.session_id === sessionId)               // solo ESTA sesión
  .sort((a, b) => Number(b.id) - Number(a.id));               // la más nueva primero
const f = filas[0] ?? null;                                   // null si no hay ninguna

// --- 2. Textos para el cliente ----------------------------------------
const TIPOS = { bano: 'Baño', cocina: 'Cocina',               // valores internos -> texto
  integral_vivienda: 'Reforma integral de vivienda',
  parcial_acabados: 'Reforma parcial de acabados', 
  pintura: 'Pintura' };
const NIVELES = { basico: 'Básico', medio: 'Medio', alto: 'Alto' };

// Un valor en una sola línea: evita que un dato con saltos de línea
// "invente" filas falsas en el resumen.
const linea = v => String(v ?? '').replace(/\s+/g, ' ').trim();

// El booleano puede llegar como true/false o como texto.
function aBooleano(v) {
  if (v === true || v === 'true') return true;                // sí
  if (v === false || v === 'false') return false;             // no
  return null;                                                // cualquier otra cosa: no vale
}

// --- 3. ¿Está completa? Si falta algo, NO se pinta ---------------------
const m2 = Number(f?.m2);                                     // superficie como número
const estructurales = aBooleano(f?.incluye_cambios_estructurales);
const telefono = limpiarTelefono(f?.telefono);               // D57: limpio, o null si no vale
const completa = !!f                                          // hay fila
  && linea(f.nombre) !== '' && linea(f.email) !== '' && linea(f.telefono) !== ''
  && f.tipo_reforma in TIPOS && f.nivel_acabados in NIVELES   // valores permitidos
  && Number.isFinite(m2) && m2 > 0                            // superficie positiva
  && estructurales !== null;                                  // sí o no, nada más

// D57: teléfono no válido -> no se pinta; el cliente recibe este texto fijo
// (responder_resumen lo enseña) y la fila se borra (rama "incompleta").
if (completa && telefono === null) {
  return [{ json: { sessionId, ok: false, motivo: 'telefono_invalido',
    texto: 'El teléfono que me has dado no parece válido: tiene que tener entre 9 y 15 cifras, con o sin prefijo internacional. ¿Me lo escribes de nuevo?' } }];
}

if (!completa) {
  // El flujo enseñará la respuesta del agente y borrará la fila (rama "incompleta").
  return [{ json: { sessionId, ok: false, motivo: f ? 'datos_incompletos' : 'sin_fila' } }];
}

// --- 4. El resumen ----------------------------------------------------
const m2Texto = m2.toLocaleString('es-ES', { maximumFractionDigits: 2 }); // 12.5 -> "12,5"
const partes = [
  'Antes de guardar nada, revisa tus datos:',
  '- Nombre: ' + linea(f.nombre),
  '- Email: ' + linea(f.email),
  '- Teléfono: ' + telefono,                                     // D57: ya limpio
  '- Reforma: ' + TIPOS[f.tipo_reforma],
  '- Superficie: ' + m2Texto + ' m²',
  '- Acabados: ' + NIVELES[f.nivel_acabados],
  '- Cambios estructurales (tirar o mover tabiques): ' + (estructurales ? 'Sí' : 'No'),
];
// Frase fija del prompt cuando el cliente no contó nada más: no aporta al cliente.
const SIN_DETALLES = 'Sin más detalles aportados por el cliente.';
const nota = limpiarNota(f.resumen_solicitud);                // D57: sin frases con datos personales
if (nota !== '' && nota !== SIN_DETALLES) {                   // solo si hay algo que enseñar
  partes.push('- Lo que hemos entendido de tu proyecto: ' + nota); // etiqueta pedida por Gabi (17/11)
}
partes.push('');                                               // línea en blanco: la pregunta no se pega a la lista (R-162-1)
partes.push('¿Es todo correcto? Responde «sí» para guardarlo, o dime qué hay que cambiar.');

return [{ json: { sessionId, ok: true, texto: partes.join('\n') } }];
